def split_name(full):
    if not isinstance(full, str) or len(full.split()) < 2:
        raise ValueError('Input must contain at least two words')
    parts = full.split()
    first, last = parts[0], parts[1]
    return (first, last)

print(split_name('Alice Smith'))

def collect_scores(students):
    return tuple(s['score'] for s in students)

students = [{'name': 'A', 'score': 10}, {'name': 'B', 'score': 20}]
print(collect_scores(students))
